/* Original place essays and explorer. Leaflet is self-hosted; map tiles load only on the map route. */
'use strict';
(() => {
 const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let context={lang:'he',spoiler:false},selected='luxembourg',scope='paris',map=null,markers=[],tileLayer=null,epoch=0,loader=null,gestures=false;
 const T=(he,en)=>context.lang==='he'?he:en, H=v=>E(typeof v==='object'&&v?v[context.lang]||v.en||'':v);
 const data=()=>window.PLACE_CONTENT?.places||[];
 const find=id=>data().find(p=>p.id===id);
 const href=(page,id)=>`/${context.lang}/${page}/${id?'?place='+encodeURIComponent(id):''}`;
 const xlink=(u,label)=>`<a href="${E(u)}" target="_blank" rel="noopener noreferrer">${H(label)}<span class="sr-only">${T(' (נפתח בלשונית חדשה)',' (opens in a new tab)')}</span> ↗</a>`;
 function setup(opts){context={...context,...opts};const q=new URLSearchParams(location.search||'').get('place');if(find(q))selected=q;if(!find(selected))selected=data()[0]?.id;}
 function credit(p){const f=p.photo;if(!f)return '';return `<figcaption>${H(f.caption)} <span>${xlink(f.sourceUrl,f.author)} · ${xlink(f.licenseUrl,f.license)}${f.modified?T(' · התאמת גודל והמרה ל־WebP',' · resized and converted to WebP'):''}</span><details><summary>${T('פרטי התמונה והרישיון','Image and licence details')}</summary>${xlink(f.sourceUrl,f.title||p.name)}<br>${T('יוצר: ','Creator: ')}${E(f.author)}<br>${H(f.transformations)}<br>${T('הרישיון המוצג חל על התמונה.','The displayed licence applies to this image.')}</details></figcaption>`;}
 function photograph(p,cls='',eager=false){const f=p.photo;return f?`<figure class="place-photo ${cls}"><img src="${E(f.src)}" width="${f.width||1200}" height="${f.height||800}" alt="${H(f.alt||f.caption)}" loading="${eager?'eager':'lazy'}" decoding="async">${credit(p)}</figure>`:'';}
 function references(p){return `<details class="place-references"><summary>${T('מקורות, הפרקים המדויקים ומיקום הסמן','Sources, exact chapters and marker placement')}</summary><h4>${T('המקום בהיסטוריה','The place in history')}</h4><div class="source-links">${(p.historySources||[]).map(s=>xlink(s.url,s.label)).join('')}</div><h4>${T('המקום ברומן','The place in the novel')}</h4><div class="source-links">${(p.novelRefs||[]).map(s=>xlink(s.url,s.label)).join('')}</div><p>${H(p.mapNote)}</p><small>${T('הפניה לטקסט המלא עשויה לחשוף ספוילרים. המספור הוא חלק · ספר · פרק, ולא מספר עמוד שמשתנה בין מהדורות.','Full-text links can reveal spoilers. References use part · book · chapter rather than page numbers that vary between editions.')}</small></details>`;}
 function plot(p){return context.spoiler?`<div class="place-novel-paragraph"><h3>${T('אצל הוגו','IN HUGO’S NOVEL')}</h3><p>${H(p.novel)}</p></div>`:`<div class="place-novel-gate"><span>${T('הקשר לרומן · ספוילרים','THE NOVEL CONNECTION · SPOILERS')}</span><p>${T('הפסקה הבאה נכנסת לאירועים ולגורלות הדמויות. אפשר להמשיך לטייל בהיסטוריה בלי לפתוח אותה.','The next paragraph enters the events and characters’ fates. You can keep exploring the history without opening it.')}</p><button class="text-button" data-place-spoilers="${E(p.id)}">${T('לקרוא גם את הקשר לרומן','Read the novel connection')} →</button></div>`;}
 function index(){return `<nav class="places-index" id="places-start" tabindex="-1" aria-label="${T('בחירת מקום לקריאה','Choose a place to read')}">${data().map((p,i)=>`<a href="${href('places',p.id)}" data-essay-select="${E(p.id)}"><span>${String(i+1).padStart(2,'0')}</span>${H(p.name)}</a>`).join('')}</nav>`;}
 function page(opts){setup(opts);return `<div class="wrap places-page"><div class="places-opening"><div><div class="eyebrow">${T('המקום אמיתי. החיים שבתוכו, של הוגו.','REAL PLACES. LIVES IMAGINED BY HUGO.')}</div><h2>${T('לצאת מהספר,<br>בלי להיפרד ממנו.','Step out of the book.<br>Keep it with you.')}</h2><p>${T('יש מקומות שהוגו המציא, ויש רחובות שהיו שם לפניו ונשארו אחרי הדמויות. תשע עצירות באתרים ששמם מופיע ברומן: תצלומים, היסטוריה והסיפור שהופך כתובת למשהו שקשה לשכוח.','Some places are Hugo’s inventions. Other streets were there before him and outlived his characters. Nine stops at places named in the novel: photographs, history and the story that makes an address hard to forget.')}</p><a class="btn" href="${href('map')}">${T('לפתוח את המפה הגאוגרפית','Open the geographic map')} →</a></div>${photograph(data()[0]||{},'places-cover',true)}</div><div class="place-method"><b>${T('איך לקרוא את הטיול','HOW TO READ THIS JOURNEY')}</b><p>${T('אלה מקומות מן הרומן, ולא רשימת אתרי צילום. תצלום עכשווי אינו הוכחה שכך נראה המקום ב־1832: ליד כל תחנה מסומן מה נשאר, מה השתנה ומה אפשר למקם רק בקירוב. פסקאות העלילה נפתחות בנפרד, לפי בחירת הספוילרים שלכם.','These places come from the novel, rather than a filming-location itinerary. A present-day photograph is not proof of how a place looked in 1832: every stop marks what survives, what changed and what can only be located approximately. Plot paragraphs follow your separate spoiler choice.')}</p></div>${index()}<div class="place-essays">${data().map((p,i)=>`<article class="place-essay" id="essay-${E(p.id)}" tabindex="-1"><div class="place-essay-visual">${photograph(p)}${p.secondaryPhoto?`<details class="place-secondary-photo"><summary>${T('עוד מבט: תיעוד והקשר','Another view: historical context')}</summary>${photograph({...p,photo:p.secondaryPhoto})}</details>`:''}<a class="place-map-link" href="${href('map',p.id)}" data-place-map="${E(p.id)}">${T('למצוא את המקום במפה','Find this place on the map')} →</a></div><div class="place-essay-copy"><div class="place-essay-number">${String(i+1).padStart(2,'0')} / ${String(data().length).padStart(2,'0')} <span>${H(p.precisionLabel)}</span></div><h2>${H(p.name)}</h2><p class="place-deck">${H(p.shortIntro)}</p><div class="place-history-paragraph"><h3>${T('המקום, לפני שהופך לסיפור','THE PLACE, BEFORE THE STORY')}</h3><p>${H(p.history)}</p></div>${plot(p)}<div class="place-location-note">${H(p.mapNote)}</div>${references(p)}${p.id==='montfermeil'?`<a class="inn-dinner-link" href="/${context.lang}/recipes/">${T('ארוחת ערב אצל טנארדייה: תפריט עכשווי ודמיוני, בעקבות המאכלים שברומן','Dinner at the Thénardiers’ inn: an imagined modern menu, inspired by foods in the novel')} →</a>`:''}<a class="text-link" href="#places-start" data-places-top>${T('חזרה לרשימת המקומות','Back to the place index')} ↑</a></div></article>`).join('')}</div><div class="place-finish"><h2>${T('ועכשיו, לחבר את הנקודות.','Now, connect the places.')}</h2><p>${T('כמה קילומטרים מפרידים בין שני מקומות. לפעמים פרק אחד מפריד בין שני עולמות.','A few kilometres separate two places. Sometimes one chapter separates two worlds.')}</p><a class="btn" href="${href('map')}">${T('לחזור אל המפה','Back to the map')} →</a></div></div>`;}
 function mapCard(){const p=find(selected);if(!p)return '';return `${photograph(p,'geo-card-photo')}<div class="geo-card-copy"><div class="eyebrow">${H(p.precisionLabel)}</div><h3 id="geo-card-title" tabindex="-1">${H(p.name)}</h3><p class="place-deck">${H(p.shortIntro)}</p><p>${H(p.mapNote)}</p>${context.spoiler?`<p class="geo-novel-summary">${H(p.novel)}</p>`:`<div class="geo-safe-note">${T('פרטי הקשר לרומן מחכים לאישור ספוילרים.','The novel connection waits for spoiler consent.')}</div>`}<a class="btn secondary" href="${href('places',p.id)}" data-place-essay="${E(p.id)}">${T('לתצלום, להיסטוריה ולסיפור המלא','Read the photo essay')} →</a>${references(p)}<div class="geo-card-nav"><button data-geo-step="-1">← ${T('המקום הקודם','Previous place')}</button><button data-geo-step="1">${T('המקום הבא','Next place')} →</button></div></div>`;}
 function filtered(){return data().filter(p=>scope==='all'||p.id!=='montfermeil');}
 function mapList(){return filtered().map(p=>`<button data-geo-place="${E(p.id)}" aria-pressed="${p.id===selected}" class="${p.id===selected?'active':''}"><span>${String(data().indexOf(p)+1).padStart(2,'0')}</span><b>${H(p.name)}</b><small>${H(p.precisionLabel)}</small></button>`).join('');}
 function loading(){return `<p class="geo-loading" role="status">${T('המפה נטענת…','Loading the map…')}</p>`;}
 function mapError(){return `<div class="geo-map-error"><h3>${T('המפה לא נטענה','The map could not load')}</h3><p role="status">${T('אפשר לנסות שוב, או להמשיך ברשימת המקומות ובתצלומים שלצדה.','Try again, or keep exploring the place list and photographs alongside it.')}</p><button class="btn" data-geo-load>${T('לנסות שוב','Try again')} →</button></div>`;}
 function mapSection(opts){setup(opts);if(selected==='montfermeil')scope='all';return `<section class="geo-explorer" id="geographic-map" aria-labelledby="geo-title"><div class="geo-intro"><div><div class="eyebrow">${T('המקומות על המפה','THE PLACES, ON THE MAP')}</div><h2 id="geo-title" tabindex="-1">${T('פריז שאפשר להתקרב אליה.','A Paris you can zoom into.')}</h2><p>${T('בחרו מקום ברשימה או סמן במפה. התצלום וההסבר נפתחים לצדו, ומשם אפשר להמשיך למאמר המצולם.','Choose a place in the list or a marker on the map. A photograph and context open beside it, with a link to the full photo essay.')}</p></div><a class="btn secondary" href="${href('places')}">${T('למסע המצולם','Read the photo essay')} →</a></div><div class="geo-controls"><div role="group" aria-label="${T('אזור במפה הגאוגרפית','Geographic map area')}"><button data-geo-scope="paris" aria-pressed="${scope==='paris'}">${T('פריז מקרוב','Paris close up')}</button><button data-geo-scope="all" aria-pressed="${scope==='all'}">${T('כולל מונפרמיי','Include Montfermeil')}</button></div><button class="text-button" data-geo-fit disabled>${T('כל המקומות במבט אחד','Show all selected places')}</button><button class="text-button" data-geo-focus disabled>${T('להתמקד במקום הנבחר','Focus selected place')}</button><button class="text-button geo-gesture-button" data-geo-gestures aria-pressed="false" hidden>${T('להפעיל מחוות מפה','Enable map gestures')}</button></div><p class="geo-touch-help">${T('במסך קטן אפשר לגלול את הדף כרגיל. השתמשו בכפתורי הזום, או הפעילו מחוות כדי לגרור את המפה.','On a small screen, scroll the page normally. Use the zoom buttons, or enable gestures to drag the map.')}</p><div class="geo-layout"><div class="geo-map-column"><div class="geo-map-stage" id="geo-map-stage"><div id="geo-map" role="region" aria-label="${T('מפה גאוגרפית אינטראקטיבית. לחצנים ברשימה מספקים חלופה מלאה.','Interactive geographic map. The place list provides a complete alternative.')}" hidden></div><div id="geo-load">${loading()}</div></div><p class="geo-map-status" id="geo-map-status" role="status">${T('מפה עכשווית להתמצאות. סמנים הם נקודות ייחוס, לא הוכחה לכתובת בדיונית או מסלול הליכה.','A present-day map for orientation. Markers are reference points, not proof of a fictional address or a walking route.')}</p><p class="geo-map-provider">${T('אריחי המפה נטענים אוטומטית מ־OpenStreetMap.','Map tiles load automatically from OpenStreetMap.')} ${xlink('https://osmfoundation.org/wiki/Privacy_Policy',T('פרטיות','Privacy'))}</p><div class="geo-place-list" id="geo-place-list" role="group" aria-label="${T('המקומות במפה','Map places')}">${mapList()}</div></div><aside class="geo-card" id="geo-card" aria-live="polite">${mapCard()}</aside></div><div class="geo-method">${T('מקום ששרד · רחוב ששמו השתנה · אזור משוער · אתר הסבר מודרני. ההבדלים מופיעים בכל כרטיס. המפה אינה טוענת שפריז של היום זהה לפריז של הוגו.','Surviving landmark · renamed street · approximate area · modern interpretation site. Each card explains the distinction. The map does not suggest today’s Paris is identical to Hugo’s.')}</div></section>`;}
 function select(id,{focus=false,pan=true,url=true}={}){if(!find(id))return;selected=id;if(id==='montfermeil'&&scope!=='all'){scope='all';refreshScope();}const card=document.getElementById('geo-card');if(card)card.innerHTML=mapCard();document.querySelectorAll('[data-geo-place]').forEach(el=>{const active=el.dataset.geoPlace===id;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});markers.forEach(({p,marker})=>marker.getElement()?.classList.toggle('is-selected',p.id===id));if(map&&pan)map.setView(find(id).coordinates,Math.max(map.getZoom(),14),{animate:false});if(url)history.replaceState(history.state,'',href('map',id));if(focus){const title=document.getElementById('geo-card-title');title?.focus({preventScroll:true});title?.scrollIntoView({block:'nearest',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches?'auto':'smooth'});}}
 function fit(){if(map){const points=filtered().map(p=>p.coordinates);if(points.length)map.fitBounds(points,{padding:[36,36],maxZoom:14,animate:false});}}
 function refreshScope(){const list=document.getElementById('geo-place-list');if(list)list.innerHTML=mapList();document.querySelectorAll('[data-geo-scope]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.geoScope===scope)));if(map){markers.forEach(({marker})=>map.removeLayer(marker));addMarkers();fit();}}
 function addMarkers(){if(!map)return;markers=filtered().map(p=>{const marker=window.L.marker(p.coordinates,{keyboard:true,title:p.name[context.lang]||p.name.en,alt:p.name[context.lang]||p.name.en,icon:window.L.divIcon({className:'geo-pin'+(p.id===selected?' is-selected':''),html:`<span>${data().indexOf(p)+1}</span>`,iconSize:[36,42],iconAnchor:[18,42]})}).addTo(map);marker.on('click',()=>select(p.id,{focus:true}));const bindKeyboard=()=>{const icon=marker.getElement();if(icon&&!icon.dataset.placeKeyboard){icon.dataset.placeKeyboard='true';icon.setAttribute('aria-label',(data().indexOf(p)+1)+'. '+(p.name[context.lang]||p.name.en));icon.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();event.stopPropagation();select(p.id,{focus:true});}});}};marker.on('add',bindKeyboard);bindKeyboard();return {p,marker};});}
 function library(){if(window.L)return Promise.resolve();if(loader)return loader;loader=new Promise((resolve,reject)=>{const el=document.createElement('script');el.src='/vendor/leaflet/leaflet.js';el.onload=resolve;el.onerror=()=>{loader=null;el.remove();reject(new Error('map-library'));};document.head.appendChild(el);});return loader;}
 async function start(takeFocus=false){const token=++epoch;const load=document.getElementById('geo-load'),root=document.getElementById('geo-map');if(!root)return;if(load)load.innerHTML=loading();try{await library();if(token!==epoch||!document.getElementById('geo-map'))return;root.hidden=false;const narrow=window.matchMedia?.('(max-width:650px), (pointer:coarse)')?.matches;gestures=false;map=window.L.map(root,{scrollWheelZoom:false,dragging:!narrow,touchZoom:!narrow,boxZoom:!narrow,doubleClickZoom:!narrow,attributionControl:true,zoomControl:false,minZoom:4,maxZoom:18});window.L.control.zoom({position:'topleft',zoomInTitle:T('להתקרב','Zoom in'),zoomOutTitle:T('להתרחק','Zoom out')}).addTo(map);window.L.control.scale({imperial:false}).addTo(map);map.attributionControl.setPrefix('<a href="https://leafletjs.com/" target="_blank" rel="noopener noreferrer">Leaflet</a>');tileLayer=window.L.tileLayer(window.PLACE_MAP_CONFIG?.tileUrl||'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'origin',keepBuffer:0,updateWhenIdle:true,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>'}).addTo(map);tileLayer.on('tileerror',()=>{const el=document.getElementById('geo-map-status');if(el)el.textContent=T('חלק מהמפה לא נטען. אפשר להמשיך ברשימה ובתצלומים, או לרענן את הדף כדי לנסות שוב.','Some map tiles could not load. The list and photographs still work; reload the page to retry.');});addMarkers();fit();const q=new URLSearchParams(location.search||'').get('place');if(find(q))select(q,{pan:true,url:false});if(load)load.innerHTML='';document.querySelector('[data-geo-gestures]')?.removeAttribute?.('hidden');document.querySelectorAll('[data-geo-fit],[data-geo-focus]').forEach(el=>el.removeAttribute('disabled'));if(takeFocus)root.focus({preventScroll:true});}catch{if(token!==epoch)return;cleanup();root.hidden=true;if(load)load.innerHTML=mapError();if(takeFocus)document.querySelector('[data-geo-load]')?.focus({preventScroll:true});}}
 function cleanup(){epoch++;if(map){map.remove();map=null;}markers=[];tileLayer=null;}
 function mount(opts){setup(opts);if(opts.route==='map')start();if(opts.route==='places'){const p=new URLSearchParams(location.search||'').get('place');if(find(p)){const el=document.getElementById('essay-'+p);el?.focus({preventScroll:true});el?.scrollIntoView({block:'start',behavior:'instant'});}}}
 function handle(e,opts){context={...context,...opts};const anchor=e.target.closest('a[data-essay-select],a[data-place-map],a[data-place-essay],a[data-places-top]');if(anchor&&(anchor.dataset?.essaySelect||anchor.dataset?.placeMap||anchor.dataset?.placeEssay||anchor.hasAttribute?.('data-places-top'))&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&(!e.button||e.button===0)){e.preventDefault();if(anchor.hasAttribute('data-places-top')){const index=document.getElementById('places-start');index?.focus({preventScroll:true});index?.scrollIntoView({block:'start',behavior:'instant'});return true;}const id=anchor.dataset.essaySelect||anchor.dataset.placeMap||anchor.dataset.placeEssay;selected=id;const next=anchor.dataset.placeMap?'map':'places';history.pushState(history.state,'',href(next,id));opts.rerender();if(next==='map'){const target=document.getElementById('geo-title');target?.focus({preventScroll:true});target?.scrollIntoView({block:'start',behavior:'instant'});}return true;}const b=e.target.closest('button');if(!b)return false;if(b.dataset.action==='language'&&['map','places'].includes(opts.route)){context.lang=context.lang==='he'?'en':'he';history.pushState(history.state,'',href(opts.route,selected));opts.rerender();if(opts.route==='map')document.querySelector('[data-action="language"]')?.focus({preventScroll:true});return true;}if(b.hasAttribute?.('data-geo-load')){start(true);return true;}if(b.hasAttribute?.('data-geo-gestures')){if(map){gestures=!gestures;map.dragging[gestures?'enable':'disable']();map.touchZoom[gestures?'enable':'disable']();b.setAttribute('aria-pressed',String(gestures));b.textContent=gestures?T('לכבות מחוות ולגלול את הדף','Disable gestures to scroll the page'):T('להפעיל מחוות מפה','Enable map gestures');}return true;}if(b.hasAttribute?.('data-geo-fit')){fit();return true;}if(b.hasAttribute?.('data-geo-focus')){select(selected,{url:false});return true;}if(b.dataset.geoPlace){select(b.dataset.geoPlace,{focus:true});return true;}if(b.dataset.geoScope){scope=b.dataset.geoScope;if(scope==='paris'&&selected==='montfermeil')selected=data()[0]?.id;refreshScope();select(selected,{pan:false});return true;}if(b.dataset.geoStep){const list=filtered(),at=list.findIndex(p=>p.id===selected);select(list[(at+Number(b.dataset.geoStep)+list.length)%list.length].id,{focus:true});return true;}if(b.dataset.placeSpoilers){const id=b.dataset.placeSpoilers;opts.reveal();const el=document.getElementById('essay-'+id);el?.focus({preventScroll:true});el?.scrollIntoView({block:'start',behavior:'instant'});return true;}return false;}
 window.PlaceAtlas={page,mapSection,mount,cleanup,handle};
})();
